/* Auditoria de Compras — Relatório da Diretoria + PDF + celular (origem: sistema-de-auditoria, PR #59).
   O portal baixa o sistema do Supabase (portal-file/PORTAL_ESPOSENDE_V4_AUTH.html). Este patch NÃO troca o
   módulo "desc" (MENC.desc): só ACRESCENTA ao módulo publicado, mantendo todas as abas e telas dele:
   - Botões "📈 Relatório Diretoria" e "📄 Baixar PDF" no topo do módulo.
   - Relatório para a Diretoria com o período/filtros da tela: economia mês a mês, melhor mês, % de desconto,
     comparação com o ano anterior, top 10 fornecedores, matriz fornecedor × mês, áreas, destaques e oportunidades,
     custo da área (opcional) para mostrar o retorno. Imprimir, Excel e PDF A4 de verdade (funciona no celular).
   - Ajustes de layout para celular no painel.
   Para voltar ao módulo como estava: remova a linha do compras-diretoria-patch.js no index.html. */
(function(){
  var HEAD="";
  var BODY="";
  function dec(b){ var s=atob(b),u=new Uint8Array(s.length); for(var i=0;i<s.length;i++)u[i]=s.charCodeAt(i); return new TextDecoder('utf-8').decode(u); }
  function enc(t){ var u=new TextEncoder().encode(t),s='',CH=0x8000; for(var i=0;i<u.length;i+=CH)s+=String.fromCharCode.apply(null,u.subarray(i,i+CH)); return btoa(s); }
  function aplicar(){
    if(typeof MENC==='undefined'||!MENC.desc)return false;
    try{
      var html=dec(MENC.desc);
      if(html.indexOf('dir-patch-js')>=0)return true;
      var h=dec(HEAD),b=dec(BODY);
      var ih=html.search(/<\/head>/i);
      html=ih>=0?html.slice(0,ih)+h+html.slice(ih):h+html;
      var ib=html.toLowerCase().lastIndexOf('</body>');
      html=ib>=0?html.slice(0,ib)+b+html.slice(ib):html+b;
      MENC.desc=enc(html);
      try{if(typeof BLOBS!=='undefined'&&BLOBS.desc){URL.revokeObjectURL(BLOBS.desc);delete BLOBS.desc;}}catch(e){}
      window.__COMPRAS_DIRETORIA_VERSAO='20261105-pr59';
    }catch(e){ console.warn('[Compras Diretoria] patch não aplicado:',e); }
    return true;
  }
  if(!aplicar())document.addEventListener('DOMContentLoaded',aplicar);
})();
